insert into public.curriculum_competencies (id, course_id, academic_level, competency_area_id, statement, status) values
  ('ug-aut300-advanced-diagnostics','aut-300','undergraduate',null,'Integrate multi-domain vehicle evidence, prioritize testable hypotheses, and justify an advanced diagnostic next step using applicable technical information.','planned'),
  ('ug-aut301-advanced-diagnostics-lab','aut-301','undergraduate',null,'Plan and execute generalized advanced diagnostic evidence collection, interpret cross-domain test results, and document a source-supported fault-isolation decision.','planned'),
  ('ug-aut310-network-communications','aut-310','undergraduate',null,'Explain generalized vehicle-network relationships, interpret communication evidence, and use applicable architecture and protocol information to justify a network diagnostic next step.','planned'),
  ('ug-aut320-hybrid-systems','aut-320','undergraduate',null,'Explain generalized hybrid energy-flow and component relationships, recognize high-voltage safety boundaries, and identify applicable information required before diagnostic or service work.','planned'),
  ('ug-aut321-hybrid-lab','aut-321','undergraduate',null,'Organize generalized hybrid laboratory evidence, recognize when work must stop for high-voltage or authorization reasons, and justify an information-supported next diagnostic step.','planned'),
  ('ug-aut331-ev-lab','aut-331','undergraduate',null,'Organize EV laboratory evidence, recognize high-voltage and charging safety boundaries, and justify a safe next diagnostic action using applicable vehicle and equipment information.','planned'),
  ('ug-aut340-battery-management','aut-340','undergraduate',null,'Explain generalized battery and management-system relationships, interpret state and health evidence in context, and identify applicable information required for safe diagnostic decisions.','planned'),
  ('ug-aut350-adas','aut-350','undergraduate',null,'Explain generalized ADAS sensor and control relationships, interpret system evidence, and identify applicable calibration, environmental, and vehicle information required before service decisions.','planned'),
  ('ug-aut360-data-analysis','aut-360','undergraduate',null,'Collect and organize generalized vehicle data, evaluate context and quality, select appropriate visual or analytical representations, and justify conclusions without overstating the evidence.','planned'),
  ('ug-aut370-embedded-systems','aut-370','undergraduate',null,'Explain generalized embedded-system and ECU relationships, trace input-processing-output flow, and distinguish conceptual architecture from implementation-specific details requiring authoritative documentation.','planned'),
  ('ug-aut380-cybersecurity','aut-380','undergraduate',null,'Identify generalized automotive cybersecurity assets, threats, and controls, interpret defensive evidence, and document risk and mitigation reasoning within authorized and ethical boundaries.','planned'),
  ('ug-aut390-connected-sdv','aut-390','undergraduate',null,'Explain generalized connected and software-defined vehicle relationships, identify data and software lifecycle dependencies, and distinguish architectural concepts from implementation-specific claims requiring authoritative information.','planned')
